css:
.sl { list-style: none; margin: 0; padding: 0; display: grid; grid-template-columns: repeat(auto-fit, minmax(min(100%, 240px), 1fr)); gap: 28px; }
.sl-i { display: flex; flex-direction: column; gap: 10px; border-top: 2px solid rgba(255,255,255,0.15); padding-top: 18px; }
.sl-i:first-child { border-top-color: #00cdfd; }
.sl-n { font-family: var(--font-heading); font-size: 13px; letter-spacing: 0.2em; color: #00cdfd; }
.sl-t { font-size: 18px; color: #f4fbff; font-weight: 600; }
.sl-d { font-size: 15px; line-height: 1.6; color: #c4d4e2; }
